export type DraftConflictDecision = {
  path: string;
  /** Keep that version of the file exactly. Keeping an absent version deletes the path. */
  keep: "yours" | "generated";
}
  | {
      path: string;
      keep: "content";
      /** Final file text, stored as UTF-8. An empty string creates an empty file. */
      content: string;
      mode: GitFileMode;
    }
  | {
      path: string;
      keep: "content";
      /** Final file bytes as canonical base64, for binary files. */
      content_base64: string;
      mode: GitFileMode;
    }
  | {
      path: string;
      keep: "content";
      /** Delete this file. */
      content: null;
    };

/** Response shape for DraftConflictDecision. */
export type DraftConflictDecisionRead = {
  path: string;
  /** Keep that version of the file exactly. Keeping an absent version deletes the path. */
  keep: ("yours" | "generated") | (string & {});
}
  | {
      path: string;
      keep: "content" | (string & {});
      /** Final file text, stored as UTF-8. An empty string creates an empty file. */
      content: string;
      mode: GitFileMode | (string & {});
    }
  | {
      path: string;
      keep: "content" | (string & {});
      /** Final file bytes as canonical base64, for binary files. */
      content_base64: string;
      mode: GitFileMode | (string & {});
    }
  | {
      path: string;
      keep: "content" | (string & {});
      /** Delete this file. */
      content: null;
    };

